import { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Container, CustomText, Button } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import customerActions from '../../../../../redux/customer/actions'
import {
  MotorSummaryStyle,
  PaymentContainer,
  PaymentSummaryContainer,
} from './index.style'
import StepsHeader from '../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  MitraCard,
  BottomActionContainerStyle,
} from '../../../../../commonStyle/index.style'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { getParamsFromUri } from '../../../../../helpers/utility'
import AmountTitle from '../../../../../components/AmountTitle'
import get from 'lodash/get'
import { removeFromLocalStorageData } from '../../../../../helpers/localstorage'
import { POLICY_DATA_KEY } from '../../../../../constants/cookies'
import { REDIRECT_PAYMENT_STATUS } from '../../../../../constants/payment'

const { getCustomerPolicy, submitCustomerPolicy, resetCustomerStore } =
  customerActions

class MotorSummary extends Component {
  static propTypes = {
    prop: PropTypes,
  }

  constructor(props) {
    super(props)
    this.policyId = getParamsFromUri.call(this, 'policyId')
  }

  componentDidMount() {
    this.props.getCustomerPolicy(this.policyId)
  }

  componentWillReceiveProps(nextProps) {
    const {
      submitCustomerPolicyStatus,
      submitPolicyError,
      resetCustomerStore,
    } = nextProps

    if (submitCustomerPolicyStatus === 'success') {
      removeFromLocalStorageData(POLICY_DATA_KEY)
      this.props.history.push({
        pathname: `/customer/payment/${this.props?.motorPolicyDetails?.product_key}/${this.policyId}`,
      })
      resetCustomerStore(['submitCustomerPolicyStatus'])
    }

    if (
      submitPolicyError &&
      submitCustomerPolicyStatus &&
      submitCustomerPolicyStatus !== 'success'
    ) {
      // show error to customer if form not submitted
      NotificationManager.error(submitCustomerPolicyStatus)
      resetCustomerStore(['submitCustomerPolicyStatus'])
    }
  }

  handleSumbitPolicy = () => {
    const { motorPolicyDetails } = this.props
    const transactionId = get(
      motorPolicyDetails,
      'transaction_ids.customer',
      ''
    )
    if (
      get(motorPolicyDetails, 'status', '') === 'PAYMENT_PENDING' &&
      transactionId
    ) {
      this.props.history.push({
        pathname: `/customer/payment/${motorPolicyDetails?.product_key}/${this.policyId}`,
      })
    } else if (
      REDIRECT_PAYMENT_STATUS.includes(
        get(motorPolicyDetails, 'payment_status', '')
      )
    ) {
      this.props.history.push(
        `/customer/payment/success/${transactionId}/${this.policyId}`
      )
    } else {
      this.props.submitCustomerPolicy(this.policyId)
    }
  }

  renderHeader = (head) => {
    return (
      <CustomText
        color={AgentColorPallette.mustard}
        size="15px"
        weight={800}
        top="8px"
        bottom="0"
      >
        {head}
      </CustomText>
    )
  }

  renderContent = (head, value, color) => {
    return (
      <div className="data">
        <CustomText color={AgentColorPallette.fontGrey} size="11px" top="8px">
          {head}
        </CustomText>
        <CustomText
          color={color || AgentColorPallette.black}
          bottom="8px"
          weight={700}
          top="2px"
        >
          {value}
        </CustomText>
      </div>
    )
  }

  renderPaymentDistribution = () => {
    const { motorPolicyDetails = {} } = this.props
    return (
      <PaymentContainer>
        <AmountTitle
          title={LANG_STRINGS.premiumPrice}
          amount={get(motorPolicyDetails, 'product.basic_premium', '')}
        />
        <hr />
        <AmountTitle
          title={LANG_STRINGS.totalBill}
          size="16px"
          color={AgentColorPallette.darkerGold}
          amount={get(motorPolicyDetails, 'total_premium', '')}
        />
      </PaymentContainer>
    )
  }

  render() {
    const {
      motorPolicyLoader,
      submitPolicyLoader,
      motorPolicyDetails = {},
    } = this.props
    const {
      policy_detail: policyDetails = {},
      customer_data: customerData = {},
    } = motorPolicyDetails
    return (
      <Container
        title={LANG_STRINGS.motorCycleInsurance}
        loader={motorPolicyLoader || submitPolicyLoader}
        showInnerHeader
        hideBottomTabs
      >
        <MotorSummaryStyle>
          <StepsHeader
            className="steps-header-custom"
            leftText={LANG_STRINGS.paymentConfirmation}
            current="3"
            totalSteps="4"
          />
          <MitraCard className="mitra-card-padding">
            {this.renderHeader(LANG_STRINGS.insuranceDetails)}
            <hr />
            {this.renderContent(
              LANG_STRINGS.category,
              get(motorPolicyDetails, 'product.package.name', '')
            )}
            {this.renderContent(
              LANG_STRINGS.period,
              `12 ${LANG_STRINGS.months}`
            )}
            {this.renderContent(LANG_STRINGS.brand, policyDetails.brand_name)}
            {this.renderContent(
              LANG_STRINGS.modelAndSeries,
              policyDetails.model_name
            )}
            {this.renderContent(
              `${LANG_STRINGS.chassisNumber} (VIN)`,
              policyDetails.chasis_number
            )}
          </MitraCard>
          <MitraCard className="mitra-card-padding">
            {this.renderHeader(LANG_STRINGS.personalInformation)}
            <hr />
            {this.renderContent(LANG_STRINGS.fullName, customerData.name)}
            {this.renderContent(LANG_STRINGS.dateOfBirth, policyDetails.dob)}
            {this.renderContent(
              LANG_STRINGS.customerPhone,
              customerData.mobile_no
            )}
            {this.renderContent(LANG_STRINGS.emailAddress, customerData.email)}
          </MitraCard>
        </MotorSummaryStyle>
        <BottomActionContainerStyle
          direction="column"
          align="stretch"
          padding="0"
        >
          <PaymentSummaryContainer>
            {this.renderPaymentDistribution()}
            <Button onClick={this.handleSumbitPolicy}>
              {LANG_STRINGS.furtherPayment}
            </Button>
          </PaymentSummaryContainer>
        </BottomActionContainerStyle>
        <NotificationContainer />
      </Container>
    )
  }
}

export default connect(
  (state) => ({
    motorPolicyDetails: state.Customer.customerPolicyData,
    submitCustomerPolicyData: state.Customer.submitCustomerPolicyData,
    submitCustomerPolicyStatus: state.Customer.submitCustomerPolicyStatus,
    submitPolicyLoader: state.Loading.SUBMIT_CUSTOMER_POLICY,
    motorPolicyLoader: state.Loading.GET_CUSTOMER_POLICY,
  }),
  {
    getCustomerPolicy,
    submitCustomerPolicy,
    resetCustomerStore,
  }
)(MotorSummary)
