import { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { Row } from '../../commonStyle/index.style'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import NumberFormat from 'react-number-format'
import ToolTip from '../ToolTip'
import { ADDON_FREE_GOLD } from '../../images'
import { LANG_STRINGS } from '../../lang'
import { AmountTitleWrapper } from './index.style'

class AmountTitle extends PureComponent {
  static propTypes = {
    title: PropTypes.any,
    size: PropTypes.string,
    amount: PropTypes.oneOfType([
      PropTypes.string,
      PropTypes.number
    ]),
    titleWeight: PropTypes.number,
    amountWeight: PropTypes.number,
    amountPrefix: PropTypes.string,
    amountColor: PropTypes.string,
    color: PropTypes.string,
    titleClassName: PropTypes.string,
    showAddonIcon: PropTypes.bool,
    className: PropTypes.string,
    showText: PropTypes.bool,
    bgColor: PropTypes.string,
    subtitle: PropTypes.oneOfType([PropTypes.node, PropTypes.string]),
  }

  render () {
    const {
      title, amount, amountColor,
      color = AgentColorPallette.black,
      amountPrefix = 'Rp ',
      size = '14px',
      className = '',
      showText = false,
      showAddonIcon = false,
      titleWeight,
      titleClassName,
      amountWeight,
      bgColor,
      subtitle
    } = this.props
    return (
      <Row justify='space-between' bgColor={bgColor} className={className}>
        <div className={`title-width ${titleClassName}`}>
          <AmountTitleWrapper
            color={color}
            size={size}
            weight={titleWeight}
          >
            {title}
            {subtitle && <p className='subtitle'>{subtitle}</p>}

          </AmountTitleWrapper>
          {
            showAddonIcon && (
              <ToolTip
                dataView={
                  <span className='addons-info-free'>
                    {LANG_STRINGS.itsFreeAddonPartOfBenefit}
                  </span>
                }
                className='addons-free-tip'
              >
                <img className='free-addon-icon' src={ADDON_FREE_GOLD} alt='Free Addon' />
              </ToolTip>
            )
          }
        </div>
        <CustomText
          size={size}
          weight={amountWeight || 800}
          color={amountColor || color}
        >
          {
            showText ? amount : (
              <NumberFormat
                // hintText="Masukan Harga"
                thousandSeparator={amountPrefix === 'Rp ' ? '.' : ','}
                decimalSeparator={amountPrefix === 'Rp ' ? ',' : '.'}
                decimalScale={2}
                className='format-input'
                prefix={amountPrefix || 'Rp '}
                value={amount}
                displayType='text'
              />
            )
          }
        </CustomText>
      </Row>
    )
  }
}

export default AmountTitle
